                            fire_at,
                            canon_note,
                            velocity,
                            channel,
                            player_note: note,
                            voice_idx,
                        });
                    }
                    held_voices.push(HeldVoiceFire {
                        voice_idx,
                        canon_notes: stack,
                        channel,
                    });
                }
                self.held.insert(
                    note,
                    HeldEntry {
                        on_beat: now,
                        anchor,
                        voices: held_voices,
                    },
                );
                self.last_input_beat = Some(now);
            }
            InputEvent::NoteOff { note, channel: _ } => {
                // Resolve global hold mode once for this NoteOff. Per-
                // voice / per-lane overrides are checked inside the
                // loop below so each voice's pending emissions can use
                // its own effective mode.
                let global_hold = world
                    .global_hold_mode
                    .lock()
                    .map(|g| *g)
                    .unwrap_or_default();
                let lane_hold = self.hold_mode;
                // PhraseEnd horizon — beat at which the current phrase
                // is considered "complete." Used by PhraseEnd to decide
                // which pending emissions still fall inside the phrase.
                let beats_per_bar = world.transport.time_signature().0 as f64;
                let phrase_end = self
                    .sequence_anchor
                    .map(|a| a + beats_per_bar)
                    .unwrap_or(now);

                // Snapshot which (voice_idx, canon_note) pairs are
                // STILL in pending_on at NoteOff entry — i.e. their
                // NoteOn hasn't fired yet. Used below to drop orphan
                // NoteOffs when HoldMode::Cancel kills the matching
                // pending NoteOn (C1 regression fix).
                let was_pending_on: std::collections::HashSet<(usize, u8)> = self
                    .pending_on
                    .iter()
                    .filter(|p| p.player_note == note)
                    .map(|p| (p.voice_idx, p.canon_note))
                    .collect();

                if let Some(held) = self.held.remove(&note) {
                    let duration = (now - held.on_beat).max(0.0);
                    for fire in held.voices {
                        let Some(voice) = self.voices.get(fire.voice_idx) else {
                            continue; // voice removed mid-flight — drop the off
                        };
                        let voice_on_relative = (held.on_beat - held.anchor).max(0.0);
                        let voice_on_fire = held.anchor
                            + voice.delay_beats as f64
                            + voice_on_relative * voice.time_ratio as f64;
                        let voice_off_fire = voice_on_fire + duration * voice.time_ratio as f64;
                        // HoldMode applies to already-emitted notes too:
                        // the pending NoteOff's fire_at must honor the
                        // effective mode, otherwise Cancel just drops
                        // pending NoteOns while leaving currently-
                        // playing notes ringing until their natural
                        // canon-voice end. Resolve per-voice (voice >
                        // lane > global) so each cascade voice can
                        // release on its own schedule.
                        let voice_hold = voice.hold_mode;
                        let effective = voice_hold.or(lane_hold).unwrap_or(global_hold);
                        let release_at = match effective {
                            HoldMode::Forever => voice_off_fire,
                            HoldMode::Cancel => now,
                            HoldMode::NearFuture { tail_beats } => {
                                voice_off_fire.min(now + tail_beats)
                            }
                            HoldMode::PhraseEnd => voice_off_fire.min(phrase_end),
                        };
                        // Send NoteOff for every pitch this voice
                        // emitted (subject + harmony stack). All fire
                        // at the same release_at — the canon voice's
                        // chord releases simultaneously.
                        for &canon_note in &fire.canon_notes {
                            // Keep one release per emitted attack. A
                            // retrigger can overlap a time-stretched
                            // predecessor at the same pitch; replacing
                            // its queued NoteOff would leave one owner
                            // sounding forever.
                            self.pending_off.push(PendingOff {
                                fire_at: release_at,
                                canon_note,
                                channel: fire.channel,
                                player_note: note,
                                voice_idx: fire.voice_idx,
                            });
                        }
                    }
                }

                // HoldMode application: walk pending_on, cancel any
                // entries seeded by THIS player note based on the
                // effective mode (voice > lane > global). Cancelling a
                // PendingOn also removes its matched PendingOff so the
                // synth doesn't receive an orphan release.
                // Snapshot voice.hold_mode by index BEFORE retain —
                // the closure borrows `self.voices` immutably via .get
                // and we want to avoid borrowing self twice during the
                // retain. Cloned/Copy so the closure can dereference.
                let voice_holds: Vec<Option<HoldMode>> =
                    self.voices.iter().map(|v| v.hold_mode).collect();
                self.pending_on.retain(|p| {
                    if p.player_note != note {
                        return true; // not seeded by this NoteOff
                    }
                    // Resolve effective HoldMode: voice override wins
                    // over lane, which wins over global. `voice_holds`
                    // is indexed by the PendingOn's `voice_idx`,
                    // captured at scheduling time, so the resolution
                    // matches what the user sees on the per-voice
                    // dropdown.
                    let voice_hold = voice_holds.get(p.voice_idx).copied().flatten();
                    let effective = voice_hold.or(lane_hold).unwrap_or(global_hold);
                    match effective {
                        HoldMode::Forever => true,
                        HoldMode::Cancel => false,
                        HoldMode::NearFuture { tail_beats } => (p.fire_at - now) <= tail_beats,
                        HoldMode::PhraseEnd => p.fire_at <= phrase_end,
                    }
                });
                // C1 fix: drop pending_off entries whose matching
                // pending_on was just cancelled by the retain above.
                // An entry is "orphaned" iff (voice_idx, canon_note)
                // was in pending_on at NoteOff entry but isn't after
                // the retain — HoldMode dropped the NoteOn, so the
                // queued NoteOff would fire to a synth that never got
                // a NoteOn. Entries that were never pending (NoteOn
                // already fired pre-NoteOff) are kept — the synth
                // still needs the release.
                let survived: std::collections::HashSet<(usize, u8)> = self
                    .pending_on
                    .iter()
                    .filter(|p| p.player_note == note)
                    .map(|p| (p.voice_idx, p.canon_note))
                    .collect();
                self.pending_off.retain(|p| {
                    if p.player_note != note {
                        return true;
                    }
                    let key = (p.voice_idx, p.canon_note);
                    !(was_pending_on.contains(&key) && !survived.contains(&key))
                });

                self.last_input_beat = Some(now);
            }
            InputEvent::Cc { .. } => {
                // Canon ignores CCs in v1; future could honor sustain
                // pedal to keep notes alive longer.
            }
        }
        LaneOutput::default()
    }

    fn tick(&mut self, world: &WorldState) -> LaneOutput {
        if !self.enabled {
            return LaneOutput::default();
        }
        let now = world.transport.total_beats();
        let mut ops: Vec<DispatchOp> = Vec::new();

        // Drain matured NoteOn emissions in fire-order.
        while let Some(p) = self.pending_on.front() {
            if p.fire_at <= now {
                let p = self.pending_on.pop_front().unwrap();
                ops.push(DispatchOp::NoteOn {
                    target: self.target,
                    note: p.canon_note,
                    velocity: p.velocity,
                    channel: p.channel,
                });
            } else {
                break;
            }
        }

        // Drain matured NoteOff emissions — linear scan + retain.
        self.pending_off.retain(|p| {
            if p.fire_at <= now {
                ops.push(DispatchOp::NoteOff {
                    target: self.target,
                    note: p.canon_note,
                    channel: p.channel,
                });
                false
            } else {
                true
            }
        });

        LaneOutput {
            ops,
            ..Default::default()
        }
    }

